import os
from typing import Any, Dict, List, Optional

from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient


def extract_tables_and_rows(
    file_path: str,
    model_id: str = "prebuilt-layout",
    endpoint: Optional[str] = None,
    key: Optional[str] = None,
) -> Dict[str, Any]:
    endpoint = endpoint or os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = key or os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    client = DocumentIntelligenceClient(
        endpoint=endpoint,
        credential=AzureKeyCredential(key),
    )

    with open(file_path, "rb") as f:
        poller = client.begin_analyze_document(
            model_id=model_id,
            body=f,
        )
    result = poller.result()

    pages: List[Dict[str, Any]] = []
    for page in getattr(result, "pages", []) or []:
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
            }
        )

    tables_output: List[Dict[str, Any]] = []
    for table_index, table in enumerate(getattr(result, "tables", []) or []):
        cells = []
        rows_map: Dict[int, List[Dict[str, Any]]] = {}

        for cell in getattr(table, "cells", []) or []:
            cell_data = {
                "row_index": getattr(cell, "row_index", None),
                "column_index": getattr(cell, "column_index", None),
                "row_span": getattr(cell, "row_span", 1),
                "column_span": getattr(cell, "column_span", 1),
                "content": getattr(cell, "content", "") or "",
                "kind": getattr(cell, "kind", None),
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": list(getattr(br, "polygon", []) or []),
                    }
                    for br in (getattr(cell, "bounding_regions", None) or [])
                ],
                "spans": [
                    {
                        "offset": getattr(span, "offset", None),
                        "length": getattr(span, "length", None),
                    }
                    for span in (getattr(cell, "spans", None) or [])
                ],
            }
            cells.append(cell_data)

            row_index = cell_data["row_index"]
            if row_index is not None:
                rows_map.setdefault(row_index, []).append(cell_data)

        rows = []
        for row_index in sorted(rows_map.keys()):
            row_cells = sorted(
                rows_map[row_index],
                key=lambda c: (
                    -1 if c["column_index"] is None else c["column_index"]
                ),
            )
            rows.append(
                {
                    "row_index": row_index,
                    "cell_count": len(row_cells),
                    "cells": row_cells,
                    "text": " | ".join(c["content"] for c in row_cells),
                }
            )

        tables_output.append(
            {
                "table_index": table_index,
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "bounding_regions": [
                    {
                        "page_number": getattr(br, "page_number", None),
                        "polygon": list(getattr(br, "polygon", []) or []),
                    }
                    for br in (getattr(table, "bounding_regions", None) or [])
                ],
                "cells": cells,
                "rows": rows,
            }
        )

    return {
        "provider": "azure-document-intelligence",
        "model_id": model_id,
        "pages": pages,
        "tables": tables_output,
    }
